<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use DigiForge\DigitalFactory\DriveHttpsProtocol as Http;
use DigiForge\DigitalFactory\DriveTransferRequest as Request;
use DigiForge\DigitalFactory\DriveOAuthResponse as OAuth;
require_once dirname(__DIR__,2).'/includes/DigitalFactory/DriveTransferRequest.php';
require_once dirname(__DIR__,2).'/includes/DigitalFactory/DriveHttpsProtocol.php';
require_once dirname(__DIR__,2).'/includes/DigitalFactory/DriveOAuthResponse.php';

final class DriveHttpsProtocolTest extends TestCase
{
 private function plan():array{return ['id'=>str_repeat('a',64),'source_sha256'=>hash('sha256','fictional-docx'),'product_id'=>1,'product_version_id'=>2];}
 public function testExactMultipartOriginalAndConversion():void {
  $p=$this->plan();foreach(['original_upload'=>Request::DOCX,'native_conversion'=>Request::DOC] as $stage=>$mime){$r=Request::build($stage,$p,[]);$w=Http::encode($r,$p,[],'fictional-docx');self::assertSame('https://www.googleapis.com/upload/drive/v3/files?'.http_build_query($r['query'],'','&',PHP_QUERY_RFC3986),$w['url']);self::assertSame('POST',$w['args']['method']);self::assertSame(0,$w['args']['redirection']);self::assertTrue($w['args']['sslverify']);self::assertFalse($w['network_request_permitted']);self::assertStringContainsString('"mimeType":"'.$mime.'"',$w['args']['body']);self::assertStringContainsString('"parents":["'.Request::FOLDER.'"]',$w['args']['body']);self::assertStringEndsWith("fictional-docx\r\n--".$w['boundary']."--\r\n",$w['args']['body']);self::assertSame((string)strlen($w['args']['body']),$w['args']['headers']['Content-Length']);self::assertArrayNotHasKey('Authorization',$w['args']['headers']);self::assertSame($w,Http::encode($r,$p,[],'fictional-docx'));}
 }
 /** @dataProvider alteredRequests */
 public function testCallerCannotWidenCanonicalWirePlan(string $field,mixed $value):void {$p=$this->plan();$r=Request::build('original_upload',$p,[]);$r[$field]=$value;$this->expectException(InvalidArgumentException::class);Http::encode($r,$p,[],'fictional-docx');}
 public static function alteredRequests():array{return [['path','https://evil.invalid/upload'],['path','/upload/drive/v3/files/foreign'],['method','DELETE'],['redirection',1],['sslverify',false],['network_request_permitted',true],['metadata',['parents'=>['foreign']]],['query',['uploadType'=>'resumable']],['headers',['Authorization'=>'SECRET']]];}
 public function testSourceDriftFailsBeforeRequestEncoding():void {$p=$this->plan();$this->expectException(InvalidArgumentException::class);Http::encode(Request::build('original_upload',$p,[]),$p,[],'changed');}
 public function testReconciliationIsExactBoundedAndNeverCreate():void {$p=$this->plan();$r=Request::reconciliation('native_conversion',$p);$w=Http::encode($r,$p,[],'');self::assertSame('GET',$w['args']['method']);self::assertSame(8193,$w['args']['limit_response_size']);self::assertStringContainsString(rawurlencode(Request::FOLDER),$w['url']);self::assertArrayNotHasKey('body',$w['args']);self::assertSame(['status'=>200,'files'=>[]],Http::decode($r,200,['content-type'=>'application/json'],'{"files":[]}'));}
 /** @dataProvider failures */
 public function testUncertainHttpFailuresNeverReturnRawBodyOrRetry(int $status):void {$p=$this->plan();$r=Request::build('native_conversion',$p,[]);self::assertSame(['status'=>$status],Http::decode($r,$status,['content-type'=>'application/json'],'{"error":"SECRET"}'));}
 public static function failures():array{return [[0],[301],[401],[403],[429],[500],[503]];}
 public function testMalformedTruncatedOversizedOrWrongMimeResponsesAreUnknown():void {$p=$this->plan();$r=Request::build('folder',$p,[]);foreach([['application/json','{',null],['text/html','{"id":"x"}',null],['application/json','{"id":"x"}',999],['application/json',str_repeat('x',Request::LIMIT+1),null],['application/json','[]',null]] as [$mime,$body,$length]){$h=['content-type'=>$mime];if($length!==null)$h['content-length']=(string)$length;self::assertSame(['status'=>0],Http::decode($r,200,$h,$body));}}
 public function testOriginalAndPdfReadbackRemainExactBytes():void {$p=$this->plan();$done=['original_upload'=>['id'=>'original'],'native_conversion'=>['id'=>'native']];foreach(['original_readback'=>[Request::DOCX,'fictional-docx'],'pdf_export'=>['application/pdf',"%PDF-1.7\nfixture"]] as $stage=>[$mime,$bytes]){$r=Request::build($stage,$p,$done);self::assertSame(['status'=>200,'bytes'=>$bytes],Http::decode($r,200,['content-type'=>$mime,'content-length'=>(string)strlen($bytes)],$bytes));}}
 public function testOAuthCandidateScopeExpiryAndRevocation():void {$r=['access_token'=>'synthetic_access','token_type'=>'Bearer','expires_in'=>3600,'scope'=>OAuth::SCOPE];$v=OAuth::describe($r,1000,1001,false);self::assertSame(4600,$v['expires_at']);self::assertFalse($v['external_execution_authorized']);self::assertStringNotContainsString('synthetic_access',json_encode($v));foreach([[$r,1000,4600,false],[$r,1000,1001,true],[$r+['error'=>'invalid_grant'],1000,1001,false],[array_replace($r,['scope'=>OAuth::SCOPE.' https://www.googleapis.com/auth/drive']),1000,1001,false],[array_replace($r,['scope'=>'']),1000,1001,false],[array_replace($r,['expires_in'=>'3600']),1000,1001,false],[array_replace($r,['access_token'=>"bad\r\nheader"]),1000,1001,false],[array_replace($r,['token_type'=>'MAC']),1000,1001,false]] as [$input,$issued,$now,$revoked]){$this->expectInvalidOAuth($input,$issued,$now,$revoked);}}
 public function testProviderErrorsAndUnrequestedMetadataAreNotExposed():void {$r=Request::build('folder',$this->plan(),[]);self::assertSame(['status'=>0],Http::decode($r,200,['content-type'=>'application/json'],'{"error":"SECRET"}'));self::assertSame(['status'=>200,'metadata'=>['id'=>'safe']],Http::decode($r,200,['content-type'=>'application/json'],'{"id":"safe","access_token":"SECRET","webContentLink":"SECRET"}'));}
 public function testBoundedLookupRejectsPaginationAndForeignProperties():void {$r=Request::reconciliation('original_upload',$this->plan());foreach(['{"files":[],"nextPageToken":"SECRET"}','{"files":[{"id":"safe","appProperties":{"access_token":"SECRET"}}]}','{"files":[{}, {}, {}]}'] as $body)self::assertSame(['status'=>0],Http::decode($r,200,['content-type'=>'application/json'],$body));}
 private function expectInvalidOAuth(array $r,int $issued,int $now,bool $revoked):void {try{OAuth::describe($r,$issued,$now,$revoked);self::fail('Invalid OAuth observation accepted.');}catch(InvalidArgumentException $e){self::assertSame('Google OAuth evidence unavailable.',$e->getMessage());}}
}
